package com.stockshield.service; import org.springframework.stereotype.Component; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.io.IOException; import java.util.concurrent.CopyOnWriteArrayList;
@Component public class EventPublisher { private final CopyOnWriteArrayList<SseEmitter> clients=new CopyOnWriteArrayList<>(); public SseEmitter subscribe(){SseEmitter e=new SseEmitter(0L); clients.add(e); e.onCompletion(()->clients.remove(e)); e.onTimeout(()->clients.remove(e)); return e;} public void publish(Object data){for(SseEmitter e:clients){try{e.send(SseEmitter.event().name("order-update").data(data));}catch(IOException x){e.complete();clients.remove(e);}}}}
